// Parity gate: replays tools/parity-trace.json (generated by tools/parity-trace.mjs from
// DesktopDrift/js/physics.js) through the C# port and requires |delta| <= 1e-6 per frame.
#nullable enable
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using NUnit.Framework;

namespace DesktopDrift.Core.Tests
{
    [TestFixture]
    public class ParityTraceTests
    {
        private static readonly string[] DriveKeys =
        {
            "thrust", "maxSpeed", "steer", "steerSmooth", "lowSpeedTurn",
            "selfAlign", "grip", "rollFriction", "driftDrag", "driftSteerBoost",
        };

        private static readonly string[] KKeys = { "PHYS_HZ", "GRIP_WOBBLE", "STEER_WOBBLE" };

        private const int Frames = 1200;
        private const double Tol = 1e-6;

        private static string? Walk(string start)
        {
            string? dir = start;
            while (!string.IsNullOrEmpty(dir))
            {
                string candidate = Path.Combine(dir, "tools", "parity-trace.json");
                if (File.Exists(candidate)) return candidate;
                dir = Path.GetDirectoryName(dir);
            }
            return null;
        }

        private static string LocateTrace()
        {
            string a = TestContext.CurrentContext.TestDirectory;
            string b = Directory.GetCurrentDirectory();
            string? found = Walk(a) ?? Walk(b);
            if (found == null)
            {
                Assert.Fail("tools/parity-trace.json not found walking up from TestDirectory='" + a +
                            "' nor from cwd='" + b + "'");
                throw new InvalidOperationException();
            }
            return found;
        }

        private static Dictionary<string, object?> LoadTrace()
        {
            object? root = Json.Parse(File.ReadAllText(LocateTrace()));
            var d = root as Dictionary<string, object?>;
            Assert.IsNotNull(d, "trace root must be an object");
            return d!;
        }

        private static Dictionary<string, object?> Obj(Dictionary<string, object?> parent, string key)
        {
            Assert.IsTrue(parent.ContainsKey(key), "missing key '" + key + "'");
            var o = parent[key] as Dictionary<string, object?>;
            Assert.IsNotNull(o, "'" + key + "' must be an object");
            return o!;
        }

        private static List<object?> Arr(Dictionary<string, object?> parent, string key)
        {
            Assert.IsTrue(parent.ContainsKey(key), "missing key '" + key + "'");
            var a = parent[key] as List<object?>;
            Assert.IsNotNull(a, "'" + key + "' must be an array");
            return a!;
        }

        private static double Num(Dictionary<string, object?> o, string key)
        {
            Assert.IsTrue(o.ContainsKey(key), "missing key '" + key + "'");
            Assert.IsInstanceOf<double>(o[key], "'" + key + "' must be a number");
            return (double)o[key]!;
        }

        [Test]
        public void Trace_HasExpectedShape()
        {
            var root = LoadTrace();

            var source = Obj(root, "source");
            Assert.AreEqual("bismark", source["car"], "source.car");
            var commit = source["commit"] as string;
            Assert.IsNotNull(commit, "source.commit");
            Assert.AreEqual(40, commit!.Length, "source.commit length");

            var drive = Obj(root, "drive");
            foreach (var key in DriveKeys) Num(drive, key);
            Assert.AreEqual(DriveKeys.Length, drive.Count, "drive key count");

            var k = Obj(root, "k");
            foreach (var key in KKeys) Num(k, key);

            Num(root, "dt");
            Assert.AreEqual(Frames, Arr(root, "steer").Count, "steer.Count");
            var frames = Arr(root, "frames");
            Assert.AreEqual(Frames, frames.Count, "frames.Count");
            for (int i = 0; i < frames.Count; i++)
            {
                var f = frames[i] as List<object?>;
                Assert.IsNotNull(f, "frame " + i + " must be an array");
                Assert.AreEqual(5, f!.Count, "frame " + i + " length");
                for (int j = 0; j < 5; j++)
                    Assert.IsInstanceOf<double>(f[j], "frame " + i + " value " + j);
            }
        }

        [Test]
        public void Replay_MatchesJsWithin1e6()
        {
            var root = LoadTrace();
            var drive = Obj(root, "drive");
            var kk = Obj(root, "k");

            var p = new DriveProfile
            {
                Thrust = Num(drive, "thrust"),
                MaxSpeed = Num(drive, "maxSpeed"),
                Steer = Num(drive, "steer"),
                SteerSmooth = Num(drive, "steerSmooth"),
                LowSpeedTurn = Num(drive, "lowSpeedTurn"),
                SelfAlign = Num(drive, "selfAlign"),
                Grip = Num(drive, "grip"),
                RollFriction = Num(drive, "rollFriction"),
                DriftDrag = Num(drive, "driftDrag"),
                DriftSteerBoost = Num(drive, "driftSteerBoost"),
            };
            var k = new PhysicsConstants
            {
                PhysHz = Num(kk, "PHYS_HZ"),
                GripWobble = Num(kk, "GRIP_WOBBLE"),
                SteerWobble = Num(kk, "STEER_WOBBLE"),
            };
            double dt = Num(root, "dt");
            var steer = Arr(root, "steer");
            var frames = Arr(root, "frames");
            Assert.AreEqual(Frames, steer.Count, "steer.Count");
            Assert.AreEqual(Frames, frames.Count, "frames.Count");

            var car = new CarState();
            var sm = new StepMotion();
            double mx = 0, my = 0, ma = 0, mvx = 0, mvy = 0;
            int worst = 0;
            double worstVal = -1;

            for (int i = 0; i < frames.Count; i++)
            {
                CarPhysics.StepCar(car, sm, (double)steer[i]!, p, k, dt);
                var f = (List<object?>)frames[i]!;
                double dx = Math.Abs(car.X - (double)f[0]!);
                double dy = Math.Abs(car.Y - (double)f[1]!);
                double da = Math.Abs(car.Angle - (double)f[2]!);
                double dvx = Math.Abs(car.Vx - (double)f[3]!);
                double dvy = Math.Abs(car.Vy - (double)f[4]!);
                mx = Math.Max(mx, dx);
                my = Math.Max(my, dy);
                ma = Math.Max(ma, da);
                mvx = Math.Max(mvx, dvx);
                mvy = Math.Max(mvy, dvy);
                double m = Math.Max(Math.Max(Math.Max(dx, dy), Math.Max(da, dvx)), dvy);
                if (m > worstVal) { worstVal = m; worst = i; }
            }

            TestContext.WriteLine("parity max|dx|=" + mx.ToString("E3", CultureInfo.InvariantCulture) + " max|dy|=" + my.ToString("E3", CultureInfo.InvariantCulture) +
                                  " max|dangle|=" + ma.ToString("E3", CultureInfo.InvariantCulture) + " max|dvx|=" + mvx.ToString("E3", CultureInfo.InvariantCulture) +
                                  " max|dvy|=" + mvy.ToString("E3", CultureInfo.InvariantCulture) + " worst frame " + worst);

            Assert.LessOrEqual(mx, Tol, "x");
            Assert.LessOrEqual(my, Tol, "y");
            Assert.LessOrEqual(ma, Tol, "angle");
            Assert.LessOrEqual(mvx, Tol, "vx");
            Assert.LessOrEqual(mvy, Tol, "vy");
        }
    }
}
